/**
 * The only module that knows where figure files are. Everything else asks it
 * for the asset behind a recipe or a part id (docs/agent-society/character-pipeline.md §9.2).
 *
 * `catalog.json` is GENERATED by `scripts/figures/build_figures.py` — every
 * base and part with its style tags, slot, attach bone, default palette and
 * source credit — and the GLBs beside it are imported through Vite, so each
 * resolves to a fingerprinted URL and a rebuilt figure never serves stale.
 */
import catalogJson from "./catalog.json";

import type { FigureArchetype, FigureRecipe, Palette } from "./figureRecipe";

export interface CatalogBase {
  /** "biped/rogue" */
  id: string;
  file: string;
  archetype: FigureArchetype;
  variant: string;
  /** "rogue" — the value a recipe's `base` carries. */
  base: string;
  label: string;
  styles: string[];
  heightM: number;
  palette: Palette;
  source: string;
  license: string;
  triangles: number;
  clips: string[];
  height_m: number;
  /**
   * Which wardrobe fits this body. A cap cut for one crown exposes the top of
   * a wider head, and two bodies of different families now share a style, so
   * the style tag alone can no longer keep them apart.
   */
  family?: string;
  /**
   * Which cut of a wrapping garment this body takes. The skull is one size
   * for every body this rig makes, but the torso runs from bulk 0.88 to 1.32,
   * so a vest, a plate, an apron and a belt come in two.
   */
  fitSize?: string | null;
  /**
   * The file this base borrows its animation from, beside it in the same
   * folder. Nine clips of a 23-bone rig outweigh a procedural body five to
   * one, so every look built on one rig shares a single copy.
   */
  clipsFrom?: string;
}

export interface CatalogPart {
  /** "headgear-knight-helmet" — the value a recipe's `parts[slot]` carries. */
  id: string;
  file: string;
  archetype: FigureArchetype;
  slot: string;
  attach: string;
  label: string;
  styles: string[];
  hides: string[];
  from_base: string;
  source: string;
  license: string;
  triangles: number;
  /** Flat cloth (a cape) has no back face of its own; the runtime renders it from both sides. */
  two_sided?: boolean;
  /**
   * Set when the piece is measured against one body family — a hat, a pair of
   * glasses. Null on anything that hangs off `chest`, `hips` or a handslot,
   * which every biped of the rig places identically.
   */
  fits_family?: string | null;
  /** Set on a garment that wraps the torso: the size class it was cut for. */
  fits_size?: string | null;
  /** True for a piece worn deliberately off centre — a shoulder bag. */
  asymmetric?: boolean;
}

export interface FigureCatalog {
  contract: number;
  styles: Record<string, string>;
  bases: CatalogBase[];
  parts: CatalogPart[];
}

export const CATALOG = catalogJson as FigureCatalog;

/** Every shipped GLB, keyed by its path under assets/society/figures/. */
const FILES = import.meta.glob("../../../assets/society/figures/**/*.glb", {
  query: "?url",
  import: "default",
  eager: true,
}) as Record<string, string>;

function urlForFile(file: string): string | null {
  const suffix = `/assets/society/figures/${file}`;
  for (const [key, url] of Object.entries(FILES)) {
    if (key.endsWith(suffix)) return url;
  }
  return null;
}

/** Base ids a recipe may still carry from before the catalog existed. */
const LEGACY_BASES: Record<string, string> = { medium: "rogue", small: "rogue", large: "rogue" };

export interface FigureAsset {
  url: string;
  /** Where the clips live, when the base does not carry its own. */
  clipsUrl: string | null;
  archetype: FigureArchetype;
  base: string;
  defaultHeightM: number;
  palette: Palette | null;
  /** True when the base ships its hair as a second primitive that headgear may hide. */
  catalog: CatalogBase | null;
}

/**
 * The catalog row behind a recipe. The archetype narrows it, but a recipe
 * whose archetype drifted from its base — a saved row from before the base
 * moved archetype, or a style switch that forgot to carry it — still finds
 * its figure by base name alone. Silently rendering the wrong figure is the
 * one outcome worth ruling out.
 */
export function catalogBaseFor(recipe: Pick<FigureRecipe, "archetype" | "base">): CatalogBase | null {
  const base = LEGACY_BASES[recipe.base] ?? recipe.base;
  return (
    CATALOG.bases.find((b) => b.archetype === recipe.archetype && b.base === base) ??
    CATALOG.bases.find((b) => b.base === base) ??
    null
  );
}

/** The archetype a base belongs to — the value a recipe must carry with it. */
export function archetypeOfBase(base: string): FigureArchetype | null {
  return catalogBaseFor({ archetype: "biped", base })?.archetype ?? null;
}

/** The GLB behind a recipe: a catalog base, or the recipe's own imported model. */
export function figureAssetFor(
  recipe: Pick<FigureRecipe, "archetype" | "base"> & { model?: string; heightM?: number },
): FigureAsset | null {
  if (recipe.model) {
    return {
      url: recipe.model,
      clipsUrl: null,
      archetype: recipe.archetype,
      base: recipe.base,
      defaultHeightM: recipe.heightM ?? 1.75,
      palette: null,
      catalog: null,
    };
  }
  const entry = catalogBaseFor(recipe);
  if (!entry) return null;
  const url = urlForFile(entry.file);
  if (!url) return null;
  return {
    url,
    clipsUrl: entry.clipsFrom ? urlForFile(entry.clipsFrom) : null,
    archetype: entry.archetype,
    base: entry.base,
    defaultHeightM: entry.heightM,
    palette: entry.palette,
    catalog: entry,
  };
}

export interface PartAsset {
  url: string;
  part: CatalogPart;
}

export function partAssetFor(partId: string): PartAsset | null {
  const part = CATALOG.parts.find((p) => p.id === partId);
  if (!part) return null;
  const url = urlForFile(part.file);
  return url ? { url, part } : null;
}

/**
 * The parts a recipe wears, resolved. An unknown id is dropped, and so is a
 * part built for another archetype — a biped cape skinned to `chest` binds to
 * nothing on Gigi's three-bone rig and would hang in the air beside her.
 * Neither is fatal: the figure renders without it.
 */
export function partAssetsFor(
  recipe: Pick<FigureRecipe, "parts"> & Partial<Pick<FigureRecipe, "archetype" | "base">>,
): PartAsset[] {
  const archetype = recipe.base
    ? (catalogBaseFor({ archetype: recipe.archetype ?? "biped", base: recipe.base })?.archetype ?? recipe.archetype)
    : recipe.archetype;
  return Object.values(recipe.parts ?? {})
    .map((id) => (id ? partAssetFor(id) : null))
    .filter((p): p is PartAsset => p !== null)
    .filter((p) => !archetype || p.part.archetype === archetype);
}

/**
 * Styles nobody creates into, whatever the catalog holds.
 *
 * `spirit` is Jarvis. There is one of him, he stands on the map, and the
 * base stays in the catalog so his card and his walker still render — but a
 * style with a cast of one is a label, not a choice, so the creator does not
 * offer it (maintainer, 2026-09-02).
 */
const RESERVED_STYLES = new Set(["spirit"]);

/**
 * Styles that have at least one base today, in catalog order; the creator
 * disables the rest. `custom` is the import lane and never appears here — it
 * has no catalog base by definition; the creator enables it once a person's
 * own GLB is in.
 */
export function stylesWithBases(): string[] {
  const live = new Set(CATALOG.bases.flatMap((b) => b.styles));
  return Object.keys(CATALOG.styles).filter((s) => live.has(s) && !RESERVED_STYLES.has(s));
}

/** True for a style the creator never lists — reserved, or the import lane. */
export function isReservedStyle(style: string): boolean {
  return RESERVED_STYLES.has(style);
}

/**
 * The bases a style offers. A style is NOT tied to one archetype — `animal`
 * is quadruped, `spirit` is spirit, `cartoon` may be either — so the
 * archetype narrows the list only when the caller asks for one.
 */
export function basesForStyle(style: string | null, archetype: FigureArchetype | null = null): CatalogBase[] {
  return CATALOG.bases.filter(
    (b) => (!archetype || b.archetype === archetype) && (!style || b.styles.includes(style)),
  );
}

export function partsForSlot(
  slot: string,
  archetype: FigureArchetype = "biped",
  style: string | null = null,
  family: string | null = null,
  size: string | null = null,
): CatalogPart[] {
  return CATALOG.parts.filter(
    (p) =>
      p.archetype === archetype &&
      p.slot === slot &&
      (!style || p.styles.includes(style)) &&
      fitsBody(p, family, size),
  );
}

/** A part with no family fits every body of its archetype; one with a family fits only that family. */
export function fitsFamily(part: CatalogPart, family: string | null): boolean {
  return !part.fits_family || !family || part.fits_family === family;
}

/** Same idea one size down: a wrapping garment fits only the girth it was cut for. */
export function fitsSize(part: CatalogPart, size: string | null | undefined): boolean {
  return !part.fits_size || !size || part.fits_size === size;
}

/** Both fit tests at once — what the creator asks before it offers a piece. */
export function fitsBody(
  part: CatalogPart,
  family: string | null,
  size: string | null | undefined,
): boolean {
  return fitsFamily(part, family) && fitsSize(part, size);
}

/**
 * Slots that hold at least one part for this archetype AND style, in the
 * order the catalog lists them. A slot with nothing to offer is not a row of
 * one "None" button — it is not a row at all.
 */
export function slotsWithParts(
  archetype: FigureArchetype = "biped",
  style: string | null = null,
  family: string | null = null,
  size: string | null = null,
): string[] {
  const seen: string[] = [];
  for (const p of CATALOG.parts) {
    if (p.archetype !== archetype) continue;
    if (style && !p.styles.includes(style)) continue;
    if (!fitsBody(p, family, size)) continue;
    if (!seen.includes(p.slot)) seen.push(p.slot);
  }
  return seen;
}

/**
 * The parts of `recipe` that the given base and style still support — what a
 * style or base switch must keep. A cape tagged `fantasy` does not survive a
 * move to `scifi`, and no biped part survives a move to a quadruped.
 */
export function keepablePartsFor(
  parts: Record<string, string>,
  archetype: FigureArchetype,
  style: string | null,
  family: string | null = null,
  size: string | null = null,
): Record<string, string> {
  const kept: Record<string, string> = {};
  for (const [slot, id] of Object.entries(parts ?? {})) {
    const part = CATALOG.parts.find((p) => p.id === id);
    if (!part || part.archetype !== archetype || part.slot !== slot) continue;
    if (style && !part.styles.includes(style)) continue;
    if (!fitsBody(part, family, size)) {
      // A vest is a vest whichever girth it was cut for: when the new body
      // takes the other cut, swap to it rather than silently undressing.
      const swap = CATALOG.parts.find(
        (p) =>
          p.slot === part.slot &&
          p.label === part.label &&
          p.archetype === archetype &&
          (!style || p.styles.includes(style)) &&
          fitsBody(p, family, size),
      );
      if (swap) kept[slot] = swap.id;
      continue;
    }
    kept[slot] = id;
  }
  return kept;
}

/** Every asset URL, for preloading the moment the section opens. */
export const FIGURE_URLS: readonly string[] = Object.values(FILES);
